import{_ as a,o,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const n="/assets/zaehlerstand-angleichen.DGfpZgVs.png",t="/assets/einstellungen-startwerte.BcWkm-3Q.png",s="/assets/zaehler-getauscht.IRuWhJKU.png",f=JSON.parse('{"title":"Correcting meter readings and swapping meters","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/02.zaehlerstaende-korrigieren.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","filePath":"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md","lastUpdated":null}'),h={name:"adapter/sourceanalytix/anleitungen/zaehlerstaende-korrigieren.md"};function l(d,e,u,c,g,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="correcting-meter-readings-and-swapping-meters" tabindex="-1">Correcting meter readings and swapping meters <a class="header-anchor" href="#correcting-meter-readings-and-swapping-meters" aria-label="Permalink to &quot;Correcting meter readings and swapping meters&quot;">​</a></h1><p><a id="correct-wrong-too-high-negative"></a></p><h2 id="how-do-i-correct-wrong-too-high-or-negative-values-after-a-reset" tabindex="-1">How do I correct wrong, too high or negative values after a reset? <a class="header-anchor" href="#how-do-i-correct-wrong-too-high-or-negative-values-after-a-reset" aria-label="Permalink to &quot;How do I correct wrong, too high or negative values after a reset?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, open the source in the SourceAnalytix instance settings, choose the action &quot;Align meter reading&quot; and enter the value your meter shows right now. SourceAnalytix does the rest immediately, without a restart. Up to v0.6.x you can only do it by hand (see below), and changing <code>cumulativeReading</code> alone is not enough.</p><p>The reason: the total (<code>cumulativeReading</code>) is always the device value plus the offset (<code>valueAtDeviceReset</code>). If you change only the total, the next value either overwrites it or is taken for a reset. The action sets both values so that they match. The terms are explained under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a>.</p><h3 id="how-to-do-it-from-v0-7-0" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance, then open your source on the &quot;Overview&quot; tab.</li><li>Under &quot;Actions&quot;, choose &quot;Align meter reading&quot;.</li><li>At &quot;What does your meter show now?&quot;, enter the reading you take from the meter.</li><li>Check the preview. It shows the old and the new total. Today&#39;s consumption and past periods stay unchanged.</li><li>Click &quot;⚡ Align&quot;. The values apply immediately.</li></ol><p><img src="'+n+'" alt="The &quot;Align meter reading&quot; dialog with preview"></p><p>If SourceAnalytix itself notices that the total and the meter don&#39;t match, it lists this on the &quot;Problems&quot; tab with the suggestion &quot;Align meter reading&quot;.</p><p>The action shifts all start values by the same amount as the total. A wrong jump that is already part of today&#39;s, this week&#39;s or this month&#39;s consumption therefore stays there. You remove that part separately via the start values, as described under <a href="#values-negative-after-entering-start">How to correct the start values</a>.</p><h3 id="repairing-costs" tabindex="-1">Repairing costs <a class="header-anchor" href="#repairing-costs" aria-label="Permalink to &quot;Repairing costs&quot;">​</a></h3><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Costs are booked continuously from the change in the total. A wrong jump upwards has therefore already been booked as costs at the price of that time, and lowering the total does not reduce the costs. Repair the costs after every correction.</p></div><p><strong>From v0.7.0:</strong> For the source, choose the action &quot;Recalculate costs from date&quot; and enter the day the error started. SourceAnalytix recalculates the costs of all affected periods using the price history. Consumption stays the same. The preview first shows how many periods are affected. SourceAnalytix only knows the consumption per period, so it spreads it evenly over the period: if the price changes in the middle of a period, the consumption is split between the two prices in proportion to time. The action does not change values in a history such as InfluxDB (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/947" target="_blank" rel="noreferrer">#947</a>).</p><p><strong>Up to v0.6.x:</strong> You can reset the costs of the running periods. Stop the instance, clear the state <code>sourceanalytix.0.&lt;device&gt;.dynamicCostMemory</code>, and set the states <code>sourceanalytix.0.&lt;device&gt;.currentYear.costs.01_currentDay</code> to <code>05_currentYear</code> to 0 (for feed-in, <code>currentYear.earnings.…</code>). After the start, SourceAnalytix recalculates them from the total and the start values using the current price. A price change within the running period is lost this way.</p><h3 id="correct-before-midnight" tabindex="-1">Correct before midnight <a class="header-anchor" href="#correct-before-midnight" aria-label="Permalink to &quot;Correct before midnight&quot;">​</a></h3><p>At midnight, SourceAnalytix writes the values of the finished periods to <code>previousDay</code>, <code>previousWeek</code> and so on, and sets the start values to the total. Aligning does not recalculate these finished values or the archive under <code>&lt;year&gt;</code>. If you correct before midnight, the error stays limited to the current day. Values already written for yesterday or in the archive have to be changed by hand, as do values in a history such as InfluxDB.</p><h3 id="up-to-v0-6-x-correcting-by-hand" tabindex="-1">Up to v0.6.x: correcting by hand <a class="header-anchor" href="#up-to-v0-6-x-correcting-by-hand" aria-label="Permalink to &quot;Up to v0.6.x: correcting by hand&quot;">​</a></h3><ol><li>Note the real meter reading and the current value of your source datapoint, both in the target unit (divide Wh by 1,000 if you calculate in kWh). Offset = real meter reading − device value. If your device already shows the real meter reading (for example an optical reader on the electricity meter), the offset is 0.</li><li>Stop the instance.</li><li>In the SourceAnalytix settings of the source datapoint, set the start values &quot;Day&quot; to &quot;Year&quot; to the total at the beginning of the period, at most the real meter reading. Save.</li><li>In the object of the source datapoint, under <code>common.custom.sourceanalytix.0</code>, set <code>valueAtDeviceReset</code> to the offset (Objects, expert mode, edit object).</li><li>Set <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code> to the real meter reading.</li><li>Start the instance and repair the costs as described above.</li></ol><p><strong>From v0.6.2:</strong> If the offset is higher than the total, for example because only <code>cumulativeReading</code> was lowered, the source keeps running and SourceAnalytix adjusts the offset itself with the next value. Up to v0.6.1, the source stopped with the error &quot;Known valueAtDeviceReset &gt; known cumulative value&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><p><strong>See also:</strong> <a href="#values-negative-after-entering-start">Negative values after entering start values</a> · <a href="#replaced-meter-device-avoid-negative">Meter or device replaced</a> · <a href="./../fehlerbehebung/log-meldungen#error-known-valueatdevicereset-known-cumulative">Error &quot;Known valueAtDeviceReset &gt; known cumulative value&quot;</a> · <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Previous periods (previous states)</a></p><p><a id="values-negative-after-entering-start"></a></p><h2 id="why-are-my-values-negative-after-i-entered-start-values" tabindex="-1">Why are my values negative after I entered start values? <a class="header-anchor" href="#why-are-my-values-negative-after-i-entered-start-values" aria-label="Permalink to &quot;Why are my values negative after I entered start values?&quot;">​</a></h2><p><strong>In short:</strong> At least one start value is larger than the current total. The consumption of a period is the total minus the start value, so it turns negative as soon as the start value is higher. Enter the total at the beginning of the period as the start value, in the target unit, and never more than the current <code>cumulativeReading</code>.</p><h3 id="the-most-common-causes" tabindex="-1">The most common causes <a class="header-anchor" href="#the-most-common-causes" aria-label="Permalink to &quot;The most common causes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What was entered</th><th>What happens</th><th>Correct</th></tr></thead><tbody><tr><td>The consumption of the period (for example 350 kWh for the year) instead of the meter reading</td><td>A small start value makes almost the whole meter reading look like consumption</td><td>The total at the beginning of the period, for example 12,300 kWh on 1 January</td></tr><tr><td>The meter reading in Wh (12,300,000) although the price definition calculates in kWh</td><td>The start value is a thousand times too large, consumption is strongly negative</td><td>A value in the target unit, so 12,300 kWh</td></tr><tr><td>The device value, although SourceAnalytix works with an offset after a reset</td><td>The start value doesn&#39;t match the total, consumption is too high or negative</td><td>Use the value from <code>cumulativeReading</code> as the reference, not the value of the device</td></tr><tr><td>A start value for &quot;Year&quot; or &quot;Month&quot; that is higher than the one for &quot;Day&quot;</td><td>The longer period turns negative</td><td>&quot;Day&quot; is always the highest start value, see below</td></tr><tr><td>0 in a field after the source was already running</td><td>The whole total shows up as consumption</td><td>SourceAnalytix only fills empty or 0 fields by itself on the first activation</td></tr></tbody></table><h3 id="how-to-correct-the-start-values" tabindex="-1">How to correct the start values <a class="header-anchor" href="#how-to-correct-the-start-values" aria-label="Permalink to &quot;How to correct the start values&quot;">​</a></h3><ol><li>Read the current total: from v0.7.0 in the source detail under &quot;Total&quot;, otherwise in the state <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>.</li><li>In the source detail, scroll to the &quot;Start values&quot; section in the &quot;Settings&quot; area. Up to v0.6.x, the fields are in the custom settings dialog of the datapoint (&quot;Objects&quot; tab, wrench icon) under &quot;Start values for the respective period&quot;.</li><li>For &quot;Day&quot;, &quot;Week&quot;, &quot;Month&quot;, &quot;Quarter&quot; and &quot;Year&quot;, enter the total at the beginning of that period, in the target unit. <ul><li>If you don&#39;t know the reading at the beginning of a period, enter the current total. The period then starts at 0 now.</li><li>Every start value is at most as large as the current total.</li><li>&quot;Day&quot; is at least as large as all the others, because the day started last. &quot;Month&quot; is at least as large as &quot;Quarter&quot;, and &quot;Quarter&quot; at least as large as &quot;Year&quot;.</li><li>You sort &quot;Week&quot; by its first day: if the week began in the previous month or the previous year, its start value may be lower than that of &quot;Month&quot; or &quot;Year&quot;.</li><li>Enter numbers without a thousands separator, with a comma or a dot as the decimal mark: <code>12475,5</code> or <code>12475.5</code>.</li></ul></li><li>Click &quot;⚡ Apply&quot;. You don&#39;t have to stop the instance for this.</li><li>With the next value from the source, SourceAnalytix recalculates the running periods. The values under <code>currentYear</code> are no longer negative.</li></ol><p><img src="'+t+'" alt="The &quot;Settings&quot; area of the source with &quot;Start values&quot; and &quot;For experts&quot; expanded"></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Start values only apply to the running period. At the next rollover (for example at midnight for &quot;Day&quot;), SourceAnalytix overwrites them with the then current total. New start values do not recalculate finished periods such as yesterday or last month.</p></div><p>If the start value is fine and the total itself is wrong, changing the start values won&#39;t help. In that case, follow <a href="#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><p><strong>From v0.7.0:</strong> The source detail checks the start values the way the wizard does. Every changed start value has to match the current total and the order of the periods. Otherwise the field shows an error and &quot;⚡ Apply&quot; stays disabled. If a value only fits after dividing by 1000, the field says, for example, &quot;Looks like Wh – did you mean 1.29 kWh?&quot;. The &quot;Problems&quot; tab also reports unsuitable start values as &quot;Start value does not fit&quot; with the suggestion &quot;Check the start values: at most the current reading, in the calculation unit.&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1267" target="_blank" rel="noreferrer">#1267</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Values or costs far too high or negative – is the unit right?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">The terms</a></p><p><a id="replaced-meter-device-avoid-negative"></a></p><h2 id="i-replaced-a-meter-or-device-how-do-i-avoid-negative-values" tabindex="-1">I replaced a meter or device: how do I avoid negative values? <a class="header-anchor" href="#i-replaced-a-meter-or-device-how-do-i-avoid-negative-values" aria-label="Permalink to &quot;I replaced a meter or device: how do I avoid negative values?&quot;">​</a></h2><p><strong>In short:</strong> Leave reset detection switched on. If the new meter starts well below the old total, for example at 0, SourceAnalytix carries on counting by itself after two values. In all other cases, use the action &quot;Meter swapped&quot; in the instance settings (from v0.7.0), ideally before the new meter delivers its first value.</p><h3 id="what-sourceanalytix-does-when-a-meter-is-swapped" tabindex="-1">What SourceAnalytix does when a meter is swapped <a class="header-anchor" href="#what-sourceanalytix-does-when-a-meter-is-swapped" aria-label="Permalink to &quot;What SourceAnalytix does when a meter is swapped&quot;">​</a></h3><table tabindex="0"><thead><tr><th>The new meter starts …</th><th>SourceAnalytix …</th><th>You …</th></tr></thead><tbody><tr><td>well below the old total (by more than the threshold)</td><td>detects a reset, confirms it with the next value and carries on counting from the old total</td><td>don&#39;t have to do anything. The log says &quot;Device reset detected …&quot;.</td></tr><tr><td>just below the old total (by no more than the threshold)</td><td>takes it for measurement noise and ignores the values until they exceed the old reading</td><td>use &quot;Meter swapped&quot;.</td></tr><tr><td>at or above the old total</td><td>sees no reset and counts the jump as consumption</td><td>use &quot;Meter swapped&quot;.</td></tr></tbody></table><p>The terms total, offset and threshold are explained under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a>.</p><h3 id="how-to-do-it-from-v0-7-0-1" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-1" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance, then open your source on the &quot;Overview&quot; tab.</li><li>Under &quot;Actions&quot;, choose &quot;Meter swapped&quot;.</li><li>Enter the end reading of the old meter, the start reading of the new meter and the date of the swap.</li><li>Check the preview and click &quot;⚡ Apply swap&quot;. The total continues from the old end reading, without a restart.</li></ol><p><img src="'+s+'" alt="The &quot;Meter swapped&quot; dialog with old end reading, new start reading and date"></p><p>If the new meter has already delivered values and the total has jumped, use &quot;Align meter reading&quot; instead and repair the costs as described under <a href="#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><h3 id="up-to-v0-6-x-setting-the-offset-by-hand" tabindex="-1">Up to v0.6.x: setting the offset by hand <a class="header-anchor" href="#up-to-v0-6-x-setting-the-offset-by-hand" aria-label="Permalink to &quot;Up to v0.6.x: setting the offset by hand&quot;">​</a></h3><ol><li>Stop the instance before the swap and note the total from <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>.</li><li>Swap the meter and note its start reading in the target unit.</li><li>Offset = old total − start reading of the new meter. If the new meter reads higher, the offset is negative. That is correct.</li><li>In the object of the source datapoint, under <code>common.custom.sourceanalytix.0</code>, set <code>valueAtDeviceReset</code> to this offset (Objects, expert mode, edit object) and start the instance.</li></ol><p>Example: the old total is 5,000 kWh, the new meter starts at 6,000 kWh, so the offset is −1,000. If the new meter later reports 6,010 kWh, <code>cumulativeReading</code> shows 5,010 kWh.</p><p><strong>From v0.6.2:</strong> If the offset after a swap is larger than the total, the source no longer stops. SourceAnalytix adjusts the offset itself with the next value (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><h3 id="device-replaced-use-an-alias-instead-of-the-device" tabindex="-1">Device replaced: use an alias instead of the device <a class="header-anchor" href="#device-replaced-use-an-alias-instead-of-the-device" aria-label="Permalink to &quot;Device replaced: use an alias instead of the device&quot;">​</a></h3><p>If the new device gets a new datapoint (for example a new Shelly with a new ID), SourceAnalytix treats it as a new source with its own folder and its own start values. You can avoid this with an ioBroker alias:</p><ol><li>Create an alias for the meter (for example under <code>alias.0</code>) that points to the datapoint of the device, and give it the unit of the meter.</li><li>Activate SourceAnalytix on the alias, not on the device.</li><li>When you replace the device, you only point the alias to the new datapoint. SourceAnalytix keeps its folder and its total.</li><li>For the meter reading of the new device, the table above then applies.</li></ol><p>The &quot;Name&quot; field in the SourceAnalytix settings is only a display label, not an ioBroker alias. Switching a datapoint directly and taking the data along is planned for later (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Older guides in the forum mention the keys <code>cumulativeValue</code>, <code>previousDeviceReset</code> or <code>valueAtDeviceInit</code>. SourceAnalytix reads none of them. From v0.6.2, <code>valueAtDeviceInit</code> is no longer written either (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1263" target="_blank" rel="noreferrer">#1263</a>).</p></div><p><strong>See also:</strong> <a href="#correct-wrong-too-high-negative">Correcting wrong values</a> · <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name, alias and output ID</a> · <a href="./betrieb-und-wartung#restart-datapoint-clean-up-old">Switching off a datapoint or starting over</a></p><p><a id="meter-restarts-after-power-loss"></a></p><h2 id="my-meter-restarts-at-0-after-a-power-failure-or-every-day-what-do-i-set" tabindex="-1">My meter restarts at 0 after a power failure or every day: what do I set? <a class="header-anchor" href="#my-meter-restarts-at-0-after-a-power-failure-or-every-day-what-do-i-set" aria-label="Permalink to &quot;My meter restarts at 0 after a power failure or every day: what do I set?&quot;">​</a></h2><p><strong>In short:</strong> Usually nothing. Leave reset detection switched on and set the threshold lower than the amount your meter drops by when it restarts. SourceAnalytix then recognises the restart as a reset and carries on counting from the old total. From v0.7.0, you find both in the source detail under &quot;Settings&quot;.</p><p>This applies to Shelly, Tasmota, sockets with an energy meter and any other device whose meter reading starts at 0 again after a power failure, a restart or at midnight. How detection works in detail is described under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a>.</p><h3 id="how-to-do-it-from-v0-7-0-2" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-2" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance, then open your source on the &quot;Overview&quot; tab.</li><li>Under &quot;Settings&quot;, tick &quot;Reset detection&quot;.</li><li>Expand &quot;For experts&quot; and check &quot;Reset detection threshold&quot;. The threshold is in the target unit, so for example in kWh, even if your device delivers Wh. SourceAnalytix ignores drops up to this size as measurement noise. <ul><li>Meter that drops to 0 during a power failure: the default of 1 works as long as the meter reading is above 1 kWh.</li><li>Daily counter (drops to 0 every night): choose a value below your smallest daily consumption, for example 0.1 kWh.</li><li>Meter with small units such as m³: also choose a small threshold, for example 0.1 m³.</li></ul></li><li>Click &quot;⚡ Apply&quot;. The setting applies immediately, without a restart.</li><li>The next time the device restarts, the log first says &quot;Waiting for another reading before confirming a possible device reset&quot;, and with the next value &quot;Device reset detected … preserving cumulative value …&quot;. The total then carries on counting from the old reading.</li></ol><p>When you add a source, the wizard asks &quot;Does the value sometimes drop to 0, e.g. after a power failure?&quot;. Reset detection is only on if you answer &quot;Yes&quot;. For Shelly and Tasmota datapoints, &quot;Yes&quot; is preselected, for all others &quot;No&quot;. If it is off for a source that drops to 0, the &quot;Problems&quot; tab shows &quot;Meter drops to 0, reset detection is off&quot; with &quot;⚡ Switch on&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>Up to v0.6.x</strong>, both settings are in the custom settings dialog of the datapoint (&quot;Objects&quot; tab, wrench icon) under &quot;Calculation settings&quot;: &quot;Device value reset detection Enabled&quot; and &quot;Threshold&quot;. From v0.7.0 they are no longer there (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><img src="'+t+'" alt="The &quot;Settings&quot; area with &quot;Reset detection&quot; and &quot;Reset detection threshold&quot; under &quot;For experts&quot;"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If the meter drops by less than the threshold, SourceAnalytix takes it for measurement noise and ignores all new values until they exceed the old reading again. For a daily counter with a threshold of 1 kWh and 0.6 kWh the day before, the first 0.6 kWh of the new day are missing. On a day with the same consumption, that is the whole day. So set the threshold lower than the smallest drop.</p></div><h3 id="daily-counters-that-start-at-0-every-night" tabindex="-1">Daily counters that start at 0 every night <a class="header-anchor" href="#daily-counters-that-start-at-0-every-night" aria-label="Permalink to &quot;Daily counters that start at 0 every night&quot;">​</a></h3><p>Daily counters such as &quot;Yield today&quot; or &quot;Consumption today&quot; work. But with every reset, the small amount is missing that the device counted between its last value before the reset and its first value afterwards. If your device also offers a total counter that is never reset (for example &quot;Total&quot;), use that one instead.</p><h3 id="if-sourceanalytix-wasn-t-running-during-the-power-failure" tabindex="-1">If SourceAnalytix wasn&#39;t running during the power failure <a class="header-anchor" href="#if-sourceanalytix-wasn-t-running-during-the-power-failure" aria-label="Permalink to &quot;If SourceAnalytix wasn&#39;t running during the power failure&quot;">​</a></h3><p>The total is stored in the state <code>cumulativeReading</code>. If the device restarted while SourceAnalytix was stopped, SourceAnalytix detects the reset with the first value after it starts. That works as long as the new device value plus the offset is still lower than the stored total by more than the threshold. If the device has already passed the old reading by then, the reset can no longer be detected. In that case, correct the total as described under <a href="#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><h3 id="power-instead-of-a-meter-reading" tabindex="-1">Power instead of a meter reading <a class="header-anchor" href="#power-instead-of-a-meter-reading" aria-label="Permalink to &quot;Power instead of a meter reading&quot;">​</a></h3><p>A power source in W has no reset, because SourceAnalytix adds up the power into a meter reading itself. If the daily counter is too imprecise for you, you can use your device&#39;s power as the source instead. What to keep in mind is described under <a href="./quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption and a meter reading from power (W)?</a>.</p><p><strong>From v0.6.2:</strong> Some devices briefly report 0 twice after a restart and then return to their old reading. Up to v0.6.1, the two zeros confirmed a reset, and the total doubled when the old reading came back. From v0.6.2, SourceAnalytix undoes the reset in this case (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a>).</p><p><strong>See also:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a> · <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Threshold and switching off reset detection</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">A counter that resets to 0 every day</a></p><p><a id="apply-real-meter-reading-cumulativereading"></a></p><h2 id="how-do-i-apply-my-real-meter-reading-cumulativereading-raw-object" tabindex="-1">How do I apply my real meter reading (cumulativeReading, RAW object)? <a class="header-anchor" href="#how-do-i-apply-my-real-meter-reading-cumulativereading-raw-object" aria-label="Permalink to &quot;How do I apply my real meter reading (cumulativeReading, RAW object)?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, you no longer have to edit an object for this. In the instance settings, open the source, choose &quot;Align meter reading&quot; and enter the reading your meter shows. SourceAnalytix sets <code>cumulativeReading</code> and the offset <code>valueAtDeviceReset</code> so that they match, immediately and without a restart. If your device already shows the real meter reading, for example through an optical reader, there is nothing to do.</p><p>The steps are under <a href="#correct-wrong-too-high-negative">How do I correct wrong, too high or negative values after a reset?</a>. You can see the offset in the source detail under &quot;For experts&quot; as <code>valueAtDeviceReset</code>.</p><h3 id="why-changing-only-cumulativereading-is-not-enough" tabindex="-1">Why changing only cumulativeReading is not enough <a class="header-anchor" href="#why-changing-only-cumulativereading-is-not-enough" aria-label="Permalink to &quot;Why changing only cumulativeReading is not enough&quot;">​</a></h3><p>The total is always the device value plus the offset. If you only write a new value to the state <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>, SourceAnalytix calculates device value plus the old offset again with the next value from the source. Your value therefore doesn&#39;t stick. The terms are explained under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">The terms</a>.</p><h3 id="why-the-raw-object-seems-locked" tabindex="-1">Why the raw object seems locked <a class="header-anchor" href="#why-the-raw-object-seems-locked" aria-label="Permalink to &quot;Why the raw object seems locked&quot;">​</a></h3><ul><li><strong>It is somewhere else than you&#39;d expect.</strong> The settings of a source are in the object of the source datapoint under <code>common.custom.sourceanalytix.0</code>, not in the folder <code>sourceanalytix.0</code>. That folder only holds the state <code>cumulativeReading</code>.</li><li><strong>It needs expert mode.</strong> You can only edit the object on the &quot;Objects&quot; tab with expert mode switched on, and the JSON has to stay valid: no stray comma, numbers without quotation marks (<code>12345.6</code>, not <code>&quot;12345.6&quot;</code>).</li><li><strong>SourceAnalytix writes into it itself.</strong> It writes the start values at every period rollover and the offset at every reset. A change you make while the instance is running can therefore be overwritten again immediately.</li></ul><p>From v0.7.0, the settings page never writes the offset either. Only SourceAnalytix itself and the actions &quot;Align meter reading&quot; and &quot;Meter swapped&quot; change it.</p><p><strong>Up to v0.6.x</strong>, the raw object is the only way: stop the instance, set <code>valueAtDeviceReset</code> and <code>cumulativeReading</code>, check the start values, start the instance. The steps are under <a href="#correct-wrong-too-high-negative">Up to v0.6.x: correcting by hand</a>.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Why are meter readings cumulative?</a> · <a href="#replaced-meter-device-avoid-negative">Meter or device replaced</a></p>',81)])])}const v=a(h,[["render",l]]);export{f as __pageData,v as default};
